import { loadFont as loadFraunces } from "@remotion/google-fonts/Fraunces";
import { loadFont as loadManrope } from "@remotion/google-fonts/Manrope";
import React from "react";
import { AbsoluteFill, Easing, Img, OffthreadVideo, Sequence, interpolate, spring, staticFile, useCurrentFrame, useVideoConfig } from "remotion";

// ONÇA PECHINCHA · grupo de achadinhos de casa e cozinha no WhatsApp. "Preço conferido."
// Copy do dono (voz o locutor, (arquivo do cliente)). Tempos = palavra na voz
// ((arquivo do cliente)); a voz entra em LEAD.
// Identidade do briefing: Verde Floresta, Creme, Coral Oferta, Verde Vivo; Fraunces Black nos títulos, Manrope nos preços.
// A onça é esperta e confiante: entradas com impulso, carimbos, lupa que "fareja" e confere.
// Preços e cards = postagens reais do grupo (briefing p. 6–8), exatamente como estão lá.
// Mesma composição em 9:16 (1080x1920) e 4:5 (1080x1350): no 4:5 o quadro de 1920 de altura é reduzido e alargado.

const { fontFamily: FR } = loadFraunces("normal", { weights: ["900"], subsets: ["latin", "latin-ext"] });
const { fontFamily: MN } = loadManrope("normal", { weights: ["500", "700", "800"], subsets: ["latin", "latin-ext"] });

export const ON_FPS = 30;
const LEAD = 0.1;
export const ON_FRAMES = Math.round(36.3 * ON_FPS);

const FOREST = "#0B3D2E";
const CREAM = "#F7F2E8";
const CORAL = "#FF5A3C";
const VIVO = "#1FB37A";
const INK = "#14201C";
const SAND = "#E6DCC8";
const GRAYG = "#5C6B64";
const WA = "#25D366";

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const k = (t: number, a: number, d: number) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
const sp = (t: number, a: number, damping = 14, stiffness = 180) =>
  spring({ frame: Math.round((t - a) * ON_FPS), fps: ON_FPS, config: { damping, stiffness } });
const img = (f: string) => staticFile(`onca/${f}`);

// largura do quadro de trabalho (1080 no 9:16; mais largo no 4:5 para o fundo cobrir as laterais)
const CwCtx = React.createContext(1080);

// ───────── texto ─────────
type W = [string, number];
const Words: React.FC<{ t: number; words: W[]; size?: number; color?: string; font?: string; weight?: number }> = ({ t, words, size = 56, color = CREAM, font = MN, weight = 700 }) => (
  <div style={{ fontFamily: font, fontWeight: weight, fontSize: size, lineHeight: 1.15, color, textAlign: "center", whiteSpace: "nowrap" }}>
    {words.map(([w, at], i) => {
      const q = k(t, at, 0.22);
      return <span key={i} style={{ display: "inline-block", margin: "0 0.12em", opacity: q, transform: `translateY(${(1 - q) * 18}px) scale(${0.7 + 0.3 * q})` }}>{w}</span>;
    })}
  </div>
);
// título em Fraunces: chega grande e assenta
const Title: React.FC<{ t: number; at: number; children: React.ReactNode; size?: number; color?: string }> = ({ t, at, children, size = 110, color = CREAM }) => {
  const s = sp(t, at, 13, 220);
  return (
    <div style={{ fontFamily: FR, fontWeight: 900, fontSize: size, lineHeight: 1.0, letterSpacing: "-0.015em", textAlign: "center", whiteSpace: "nowrap", color,
      opacity: Math.min(1, s * 3), transform: `scale(${1.5 - 0.5 * s})` }}>{children}</div>
  );
};
const Block: React.FC<{ t: number; top: number; at: number; out?: number; gap?: number; children: React.ReactNode }> = ({ t, top, at, out, gap = 10, children }) => {
  if (t < at - 0.05 || (out !== undefined && t > out + 0.14)) return null;
  const o = out === undefined ? 0 : k(t, out, 0.12);
  return (
    <div style={{ position: "absolute", left: 120, right: 120, top, display: "flex", flexDirection: "column", alignItems: "center", gap, opacity: 1 - o, transform: `scale(${1 - o * 0.08})` }}>{children}</div>
  );
};

// ───────── cena e transições ─────────
type Tr = "none" | "cut" | "slideL" | "slideUp" | "circle" | "wipe" | "zoom" | "iris" | "band";
const TD = 0.38;
const Scene: React.FC<{ t: number; a: number; b: number; tr: Tr; bg: string; cam?: [number, number]; drift?: number; children: React.ReactNode }> = ({ t, a, b, tr, bg, cam = [1, 1.06], drift = -40, children }) => {
  const cw = React.useContext(CwCtx);
  if (t < a || t > b + TD) return null;
  const q = tr === "none" || tr === "cut" ? 1 : k(t, a, TD);
  let clip = "none", tf = "", op = 1;
  if (tr === "band") clip = `polygon(0 ${(1 - q) * 100}%, 100% ${(1 - q) * 100 - 20 * (1 - q)}%, 100% 100%, 0 100%)`;
  if (tr === "wipe") clip = `polygon(0 0, ${q * 125}% 0, ${q * 125 - 25}% 100%, 0 100%)`;
  if (tr === "slideL") tf = `translateX(${(1 - q) * 100}%)`;
  if (tr === "slideUp") tf = `translateY(${(1 - q) * 100}%)`;
  if (tr === "zoom") { tf = `scale(${1.3 - 0.3 * q})`; op = Math.min(1, q * 1.7); }
  if (tr === "circle") clip = `circle(${q * 120}% at 50% 50%)`;
  if (tr === "iris") clip = `inset(${(1 - q) * 50}% ${(1 - q) * 50}% round ${(1 - q) * 200}px)`;
  const p = lin(t, a, b + TD);
  const z = Math.max(cam[0] + (cam[1] - cam[0]) * p, 1.006 + (Math.abs(drift * p) * 2) / 1920);
  return (
    <AbsoluteFill style={{ clipPath: clip, transform: tf || undefined, opacity: op, overflow: "hidden", background: bg }}>
      <AbsoluteFill style={{ transform: `translateY(${(drift * p).toFixed(1)}px) scale(${z.toFixed(4)})` }}>
        <div style={{ position: "absolute", top: 0, height: 1920, width: 1080, left: (cw - 1080) / 2 }}>{children}</div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

// ───────── peças ─────────
// foto do produto em cartão creme, com zoom lento por dentro
const Photo: React.FC<{ t: number; at: number; src: string; x?: number; y: number; w: number; rot?: number; from?: "up" | "down" | "big"; z?: [number, number]; gray?: number; radius?: number; extra?: string; dur?: number }> = ({ t, at, src, x, y, w, rot = 0, from = "big", z = [1.14, 1.0], gray = 0, radius = 44, extra = "", dur = 4 }) => {
  const s = sp(t, at, 14, 170);
  const e = lin(t, at, at + dur);
  const enter = from === "big" ? `scale(${1.5 - 0.5 * s})` : `translateY(${(1 - s) * (from === "up" ? -1200 : 1400)}px) rotate(${(1 - s) * (from === "up" ? -14 : 14)}deg)`;
  return (
    <div style={{ position: "absolute", left: x === undefined ? (1080 - w) / 2 : x, top: y, width: w, height: w, borderRadius: radius, overflow: "hidden", background: "#fff",
      border: `12px solid ${CREAM}`, boxShadow: "0 40px 90px rgba(0,0,0,0.35)", opacity: Math.min(1, s * 3), transform: `${enter} rotate(${rot}deg) ${extra}` }}>
      <Img src={img(src)} style={{ width: "100%", height: "100%", objectFit: "cover", transform: `scale(${z[0] + (z[1] - z[0]) * e})`, filter: gray ? `grayscale(${gray}) brightness(${1 - 0.25 * gray})` : undefined }} />
    </div>
  );
};

// preço que conta até o valor real, preço antigo riscado e % OFF
const Price: React.FC<{ t: number; at: number; value: number; old: string; off: string; note?: string; dark?: boolean }> = ({ t, at, value, old, off, note, dark }) => {
  const s = sp(t, at, 12, 220);
  const v = value * k(t, at, 0.8);
  const [int, dec] = v.toFixed(2).split(".");
  const strike = k(t, at + 0.15, 0.35);
  const chip = sp(t, at + 0.75, 11, 240);
  const ink = dark ? INK : CREAM;
  return (
    <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 14, opacity: Math.min(1, s * 3) }}>
      <div style={{ position: "relative", fontFamily: MN, fontWeight: 700, fontSize: 46, color: dark ? GRAYG : SAND }}>
        de {old}
        <div style={{ position: "absolute", left: -6, top: "54%", height: 6, borderRadius: 3, background: CORAL, width: `calc(${strike * 100}% + 12px)` }} />
      </div>
      <div style={{ display: "flex", alignItems: "flex-start", padding: "18px 54px 26px", borderRadius: 40, background: CORAL, boxShadow: "0 26px 70px rgba(255,90,60,0.35)",
        transform: `scale(${0.4 + 0.6 * s}) rotate(${(1 - s) * -8}deg)` }}>
        <span style={{ fontFamily: MN, fontWeight: 800, fontSize: 64, color: CREAM, marginTop: 26, marginRight: 14 }}>R$</span>
        <span style={{ display: "inline-block", minWidth: 330, textAlign: "right", fontFamily: MN, fontWeight: 800, fontSize: 176, lineHeight: 1, color: CREAM, letterSpacing: "-0.04em", fontVariantNumeric: "tabular-nums" }}>{int}</span>
        <span style={{ fontFamily: MN, fontWeight: 800, fontSize: 80, color: CREAM, marginTop: 14, fontVariantNumeric: "tabular-nums" }}>,{dec}</span>
      </div>
      <div style={{ display: "flex", gap: 18, alignItems: "center", opacity: Math.min(1, chip * 3), transform: `scale(${chip})` }}>
        <span style={{ fontFamily: MN, fontWeight: 800, fontSize: 44, color: dark ? CREAM : FOREST, background: VIVO, padding: "8px 26px", borderRadius: 30 }}>{off}</span>
        {note && <span style={{ fontFamily: MN, fontWeight: 700, fontSize: 44, color: ink }}>{note}</span>}
      </div>
    </div>
  );
};

// card real do grupo (postagem como aparece no WhatsApp)
const Card: React.FC<{ t: number; at: number; src: string; cx: number; y: number; w: number; rot?: number; ratio: number }> = ({ t, at, src, cx, y, w, rot = 0, ratio }) => {
  const s = sp(t, at, 14, 170);
  return (
    <div style={{ position: "absolute", left: cx - w / 2, top: y, width: w, height: w * ratio, borderRadius: 30, overflow: "hidden", boxShadow: "0 36px 80px rgba(11,61,46,0.35)",
      opacity: Math.min(1, s * 3), transform: `translateY(${(1 - s) * 1300}px) rotate(${rot + (1 - s) * 18}deg)` }}>
      <Img src={img(src)} style={{ width: "100%", height: "100%", objectFit: "cover" }} />
    </div>
  );
};

const Logo: React.FC<{ t: number; at: number; size: number; top: number; spin?: boolean }> = ({ t, at, size, top, spin = true }) => {
  const s = sp(t, at, 12, 190);
  return (
    <Img src={img("logo-redondo.png")} style={{ position: "absolute", left: (1080 - size) / 2, top, width: size, height: size, opacity: Math.min(1, s * 3),
      transform: `scale(${0.3 + 0.7 * s}) rotate(${spin ? (1 - s) * -25 : 0}deg)`, filter: "drop-shadow(0 30px 60px rgba(0,0,0,0.3))" }} />
  );
};

const Check: React.FC<{ t: number; at: number; size?: number; bg?: string; fg?: string }> = ({ t, at, size = 64, bg = VIVO, fg = CREAM }) => {
  const s = sp(t, at, 11, 240);
  const d = k(t, at + 0.08, 0.28);
  return (
    <svg width={size} height={size} viewBox="0 0 100 100" style={{ flex: "none", transform: `scale(${s})` }}>
      <circle cx={50} cy={50} r={48} fill={bg} />
      <path d="M28 52 L44 67 L73 35" fill="none" stroke={fg} strokeWidth={11} strokeLinecap="round" strokeLinejoin="round" strokeDasharray={70} strokeDashoffset={70 * (1 - d)} />
    </svg>
  );
};

const WaIcon: React.FC<{ size: number; color?: string; bg?: string }> = ({ size, color = "#fff", bg = WA }) => (
  <svg width={size} height={size} viewBox="0 0 100 100" style={{ flex: "none" }}>
    <circle cx={50} cy={50} r={50} fill={bg} />
    <path d="M50 20 a30 30 0 0 0 -26 45 l-4 15 15 -4 a30 30 0 1 0 15 -56 z" fill="none" stroke={color} strokeWidth={6} strokeLinejoin="round" />
    <path d="M39 37 c-2 4 0 11 6 17 s13 8 17 6 l2 -5 -7 -4 -3 3 c-3 -1 -7 -5 -8 -8 l3 -3 -4 -7 z" fill={color} />
  </svg>
);

// lupa da onça: passa pelos achados e confere cada um
const Lupa: React.FC<{ x: number; y: number; s: number }> = ({ x, y, s }) => (
  <svg width={300} height={300} viewBox="0 0 100 100" style={{ position: "absolute", left: x - 110, top: y - 110, transform: `scale(${s})`, transformOrigin: "37% 37%", filter: "drop-shadow(0 20px 30px rgba(0,0,0,0.3))" }}>
    <line x1={60} y1={60} x2={90} y2={90} stroke={FOREST} strokeWidth={13} strokeLinecap="round" />
    <circle cx={37} cy={37} r={28} fill="rgba(247,242,232,0.25)" stroke={FOREST} strokeWidth={9} />
    <path d="M22 28 a18 18 0 0 1 12 -10" fill="none" stroke="#fff" strokeWidth={5} strokeLinecap="round" opacity={0.8} />
  </svg>
);

// carimbo
const Stamp: React.FC<{ t: number; at: number; children: React.ReactNode; color?: string; size?: number; rot?: number }> = ({ t, at, children, color = CORAL, size = 130, rot = -12 }) => {
  const s = sp(t, at, 10, 260);
  if (t < at) return null;
  return (
    <div style={{ fontFamily: FR, fontWeight: 900, fontSize: size, lineHeight: 1, color, border: `12px solid ${color}`, borderRadius: 30, padding: "16px 44px 26px", background: "rgba(247,242,232,0.92)",
      opacity: Math.min(1, s * 4), transform: `scale(${2.4 - 1.4 * s}) rotate(${rot}deg)`, whiteSpace: "nowrap" }}>{children}</div>
  );
};

// celular com a gravação de tela do grupo rolando
const Phone: React.FC<{ t: number; a: number; b: number; from: number; y: number; w: number }> = ({ t, a, b, from, y, w }) => {
  const s = sp(t, a, 15, 170);
  const h = w * 2.08;
  return (
    <div style={{ position: "absolute", left: (1080 - w) / 2, top: y, width: w, height: h, borderRadius: 70, background: INK, padding: 18, boxSizing: "border-box",
      boxShadow: "0 50px 100px rgba(0,0,0,0.45)", opacity: Math.min(1, s * 3), transform: `translateY(${(1 - s) * 1200}px) rotate(${(1 - s) * 10}deg)` }}>
      <div style={{ width: "100%", height: "100%", borderRadius: 54, overflow: "hidden", background: "#000" }}>
        <Sequence from={Math.round((a + LEAD) * ON_FPS)} durationInFrames={Math.round((b - a + 0.6) * ON_FPS)} layout="none">
          <OffthreadVideo src={img("grupo.mp4")} muted startFrom={Math.round(from * ON_FPS)} style={{ width: "100%", height: "100%", objectFit: "cover", objectPosition: "50% 0%" }} />
        </Sequence>
      </div>
    </div>
  );
};

// etiqueta lateral apontando parte do card
const Callout: React.FC<{ t: number; at: number; top: number; children: React.ReactNode }> = ({ t, at, top, children }) => {
  const s = sp(t, at, 12, 230);
  return (
    <div style={{ position: "absolute", right: 120, top, display: "flex", alignItems: "center", gap: 14, padding: "14px 34px 18px 22px", borderRadius: 50, background: CORAL,
      boxShadow: "0 20px 50px rgba(0,0,0,0.35)", opacity: Math.min(1, s * 3), transform: `translateX(${(1 - s) * 300}px) scale(${0.6 + 0.4 * s})` }}>
      <Check t={t} at={at + 0.1} size={60} bg={CREAM} fg={CORAL} />
      <span style={{ fontFamily: FR, fontWeight: 900, fontSize: 68, color: CREAM, lineHeight: 1 }}>{children}</span>
    </div>
  );
};

// marca de destaque sobre o card
const Ring: React.FC<{ t: number; at: number; x: number; y: number; w: number; h: number }> = ({ t, at, x, y, w, h }) => {
  const s = k(t, at, 0.3);
  return <div style={{ position: "absolute", left: x, top: y, width: w, height: h, borderRadius: 26, border: `8px solid ${CORAL}`, opacity: s, transform: `scale(${1.15 - 0.15 * s})` }} />;
};

// linha de benefício
const Perk: React.FC<{ t: number; at: number; title: string; sub?: string }> = ({ t, at, title, sub }) => {
  const s = sp(t, at, 14, 200);
  return (
    <div style={{ width: 840, display: "flex", alignItems: "center", gap: 34, padding: "34px 44px", borderRadius: 40, background: CREAM, boxShadow: "0 24px 60px rgba(11,61,46,0.16)", boxSizing: "border-box",
      opacity: Math.min(1, s * 3), transform: `translateX(${(1 - s) * 500}px) rotate(${(1 - s) * 6}deg)` }}>
      <Check t={t} at={at + 0.12} size={96} />
      <div>
        <div style={{ fontFamily: FR, fontWeight: 900, fontSize: 68, lineHeight: 1, color: FOREST, whiteSpace: "nowrap" }}>{title}</div>
        {sub && <div style={{ marginTop: 10, fontFamily: MN, fontWeight: 700, fontSize: 40, color: GRAYG, whiteSpace: "nowrap" }}>{sub}</div>}
      </div>
    </div>
  );
};

// ───────── cenas de produto (abertura) ─────────
const Product: React.FC<{ t: number; a: number; name: string; nameAt: number; photo: string; priceAt: number; value: number; old: string; off: string; note?: string; dark?: boolean; from?: "up" | "down" | "big" }> = ({ t, a, name, nameAt, photo, priceAt, value, old, off, note, dark, from }) => (
  <>
    <Block t={t} top={230} at={nameAt}>
      <Title t={t} at={nameAt} size={104} color={dark ? FOREST : CREAM}>{name}</Title>
    </Block>
    <Photo t={t} at={a + 0.02} src={photo} y={420} w={720} from={from} rot={from === "big" ? 0 : from === "up" ? -2 : 2} z={[1.32, 1.0]} dur={3} />
    <div style={{ position: "absolute", left: 120, right: 120, top: 1240, display: "flex", justifyContent: "center" }}>
      {t > priceAt - 0.05 && <Price t={t} at={priceAt} value={value} old={old} off={off} note={note} dark={dark} />}
    </div>
  </>
);

export const Onca: React.FC = () => {
  const frame = useCurrentFrame();
  const { width, height } = useVideoConfig();
  const t = frame / ON_FPS - LEAD;
  const sc = height / 1920;
  const cw = width / sc;
  return (
    <AbsoluteFill style={{ background: FOREST, overflow: "hidden" }}>
      <CwCtx.Provider value={cw}>
        <div style={{ position: "absolute", left: 0, top: 0, width: cw, height: 1920, transform: `scale(${sc})`, transformOrigin: "0 0" }}>
          {/* 1 · Mesa de jantar por 328 */}
          <Scene t={t} a={-0.2} b={3.38} tr="none" bg={FOREST} cam={[1.08, 1.0]} drift={0}>
            <Product t={t} a={-0.1} name="Mesa de jantar" nameAt={0.11} photo="foto-mesa-jantar.jpg" priceAt={1.27} value={328.06} old="R$ 699,00" off="53% OFF" from="big" />
          </Scene>
          {/* 2 · Panela de pressão por 132 */}
          <Scene t={t} a={3.38} b={6.25} tr="slideL" bg={CREAM} cam={[1, 1.06]} drift={-30}>
            <Product t={t} a={3.42} name="Panela de pressão" nameAt={3.55} photo="foto-panela-pressao.jpg" priceAt={4.82} value={132.21} old="R$ 429,90" off="69% OFF" note="com cupom" dark from="down" />
          </Scene>
          {/* 3 · Jogo de panelas por 266 */}
          <Scene t={t} a={6.25} b={9.1} tr="wipe" bg={FOREST} cam={[1.06, 1.0]} drift={30}>
            <Product t={t} a={6.3} name="Jogo de panelas" nameAt={6.42} photo="foto-jogo-panelas.jpg" priceAt={7.5} value={266.55} old="R$ 599,99" off="55% OFF" from="up" />
          </Scene>

          {/* 4 · Parece mentira? (as três fotos voltam em leque) */}
          <Scene t={t} a={9.1} b={10.62} tr="zoom" bg={CORAL} cam={[1, 1.08]} drift={0}>
            <Block t={t} top={300} at={9.36} gap={6}>
              <Words t={t} size={84} words={[["Parece", 9.4]]} />
              <Title t={t} at={9.74} size={200} color={FOREST}>mentira?</Title>
            </Block>
            <Photo t={t} at={9.18} src="foto-mesa-jantar.jpg" x={70} y={900} w={400} rot={-10} from="down" radius={34} />
            <Photo t={t} at={9.28} src="foto-jogo-panelas.jpg" x={610} y={900} w={400} rot={10} from="down" radius={34} />
            <Photo t={t} at={9.38} src="foto-panela-pressao.jpg" x={330} y={1010} w={420} rot={0} from="down" radius={34} />
          </Scene>

          {/* 5 · os posts reais já passaram pelo grupo */}
          <Scene t={t} a={10.62} b={14.0} tr="circle" bg={CREAM} cam={[1, 1.07]} drift={-40}>
            <Block t={t} top={210} at={10.78} gap={6}>
              <Title t={t} at={10.78} size={100} color={FOREST}>Essas ofertas</Title>
              <Words t={t} size={54} color={FOREST} words={[["já", 11.7], ["passaram", 11.92], ["pelo", 12.5], ["grupo", 12.72]]} />
            </Block>
            <Card t={t} at={11.08} src="card-mesa-jantar.jpg" cx={260} y={560} w={330} rot={-9} ratio={2.08} />
            <Card t={t} at={11.92} src="card-jogo-panelas.jpg" cx={820} y={560} w={330} rot={9} ratio={2.064} />
            <Card t={t} at={11.5} src="card-panela-pressao.jpg" cx={540} y={520} w={360} rot={0} ratio={2.262} />
            <Logo t={t} at={13.0} size={360} top={1340} />
          </Scene>

          {/* 6 · oferta boa acaba rápido / quem vê tarde, perde */}
          <Scene t={t} a={14.0} b={18.12} tr="slideUp" bg={FOREST} cam={[1.0, 1.08]} drift={-30}>
            <Block t={t} top={230} at={14.14} out={16.3} gap={8}>
              <Title t={t} at={14.34} size={110}>Oferta boa</Title>
              <Words t={t} size={60} color={SAND} words={[["acaba", 15.3], ["rápido.", 15.72]]} />
            </Block>
            <Block t={t} top={230} at={16.43} gap={8}>
              <Words t={t} size={60} color={SAND} words={[["Quem", 16.43], ["vê", 16.61], ["tarde,", 16.79]]} />
              <Title t={t} at={17.39} size={130} color={CORAL}>perde.</Title>
            </Block>
            <Photo t={t} at={14.05} src="foto-batedeira.jpg" y={560} w={680} from="down" gray={k(t, 17.39, 0.4)} z={[1.3, 1.0]} dur={3.3}
              extra={`scale(${1 - 0.2 * lin(t, 14.6, 17.35)}) rotate(${-4 * lin(t, 14.6, 17.35)}deg)`} />
            {/* tempo da oferta acabando */}
            <div style={{ position: "absolute", left: 200, width: 680, top: 1330, height: 30, borderRadius: 15, background: "rgba(247,242,232,0.18)", overflow: "hidden" }}>
